<p>Якщо ви користувалися кредитними картками, оформлювали позики або виступали поручителем, варто перевірити свою кредитну історію. В Україні інформацію про кредити та їх обслуговування зберігають бюро кредитних історій. Дані в різних бюро можуть відрізнятися, оскільки не всі кредитори передають інформацію до кожного з них.</p>
