<p>Відновити видалені повідомлення у Viber можна переважно за допомогою резервної копії, створеної до видалення листування. На Android для цього використовується Google Диск, а на iPhone — iCloud. Якщо копії немає, стандартного способу повернути чат зазвичай не існує. Тому автоматичне резервне копіювання краще налаштувати заздалегідь.</p>
