<p>Перед тривалим зберіганням куртка повинна бути повністю чистою та сухою. Не стискайте натуральний пуховик у маленький пакет на багато місяців, якщо виробник не рекомендує такий спосіб. Краще використовувати просторий чохол і зберігати річ у сухому місці.</p>

