<p>Щоб позбутися молі в шафі, потрібно знайти личинки, очистити заражені речі та ретельно прибрати місце їхнього перебування. Ароматичні саше й феромонні пастки можуть бути лише допоміжними засобами. Найкращий захист — чистий одяг перед зберіганням, регулярний огляд шафи та герметичне пакування сезонних речей.</p>
