<p>Попросіть помічника увімкнути стартер, а самі стежте за показами. Нормальним вважається, якщо напруга не падає нижче приблизно 9,5–10 В. Якщо вона провалюється значно нижче, акумулятор не віддає потрібний струм і, імовірно, зношений.</p>

