<p>Запустіть двигун і підніміть оберти приблизно до 2000 за хвилину. Напруга на клемах має бути в межах 13,8–14,5 В. Якщо вона нижча за 13,5 В, акумулятор не підзаряджається: причиною може бути генератор, натяг ременя чи контакти. Значення понад 14,8–15 В свідчать про збій регулятора напруги, який «перезаряджає» АКБ і швидко його вбиває.</p>

